// Faithful web hierarchy from native bccac84 (Nov 11); fictional, session-only data.
import {mathBands,mathBandDetails,sampleTreasures} from './demo-model.mjs';
const glyph=name=>'<svg aria-hidden="true"><use href="/assets/parent-icons.svg#'+name+'"></use></svg>';
const row=(label,value,action='')=>'<'+(action?'button type="button" data-parent-action="'+action+'"':'div')+' class="ios-row"><span>'+label+'</span><span>'+value+'<i>›</i></span></'+(action?'button':'div')+'>';
const group=(title,body,target='')=>'<section class="ios-group"'+(target?' data-parent-target="'+target+'"':'')+'>'+(title?'<h4 class="ios-section-label">'+title+'</h4>':'')+'<div class="ios-inset">'+body+'</div></section>';
const button=(action,label)=>'<button class="ios-native-action" data-parent-action="'+action+'">'+label+'</button>';
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const childSettings=()=>({speed:1,style:0,topics:{},band:0,step:0,rewards:true,deleted:[],appliedBand:0,appliedStep:0,stars:18,owned:['starter-cap','starter-scarf','starter-bow'],outfit:{hat:'starter-cap'}});
export const initialParentState=()=>({child:0,range:0,detail:null,confirm:false,prepared:false,connected:true,disconnect:false,notice:'',route:null,filter:'All',search:'',reportGuide:false,stars:18,owned:['starter-cap','starter-scarf','starter-bow'],outfit:{hat:'starter-cap'},...childSettings(),profiles:{}});
export function switchParentChild(s){s.profiles[s.child]=Object.fromEntries(Object.keys(childSettings()).map(k=>[k,s[k]]));s.child=1-s.child;Object.assign(s,s.profiles[s.child]||childSettings());s.detail=null;s.confirm=false;s.notice='';s.search='';s.filter='All';}
export const parentChapters=[
 {id:'overview',label:'Overview',tab:0,title:'Their day.\nAt a glance.',summary:'Questions, Math and Stories in one calm view. Choose a child and a date range.',why:'The overview gives each activity equal space. Counts open the underlying records, so a parent can move from a quick glance to the actual exchange. A visible update time makes the information’s freshness clear.',limit:'Counts describe saved activity, not a child’s ability. Offline discovery listening is not included.'},
 {id:'activity',label:'Activity',tab:1,title:'See the words.\nKeep the context.',summary:'Read a question and its answer. Look back at Math practice or a finished story.',why:'Filters and search help you find a particular moment without reading everything. Math separates independent work from supported practice. Individual records have a confirmed delete action. Learning records are for family reports and learning support, with no commercial profiling.',limit:'These are fictional records. Deleting a sample changes only this preview.'},
 {id:'learning',label:'Learning pace',tab:2,title:'A starting point.\nRoom to grow.',summary:'Choose a Math band and a small step within it. The next new project starts there.',why:'Seven reference bands each have three steps. The first two bands use three answer choices, without division or sharing. Later work can use number entry. An explicit parent adjustment applies to the next new project; unfinished work, practice history and Stars stay intact.',limit:'The app adapts from practice evidence over time. This website uses prepared examples and does not assess a child.'},
 {id:'reading',label:'Reading',tab:2,title:'A little help.\nRight there.',summary:'Set the reading pace. On the Watch, a tap on a word opens Hear, Sounds and Meaning.',why:'Word help stays in a small bubble over the story, so the child keeps their place. They can move between words and tap outside to return. Reading speed has a playable sample before you save your choice. Downloaded books remain available offline.',limit:'The web example uses the original Pip story and narration. Word explanations are prepared text; Hear plays a word from the recorded page.'},
 {id:'topics',label:'Safeguards',tab:2,title:'Your family.\nYour guidance.',summary:'Choose how supported topics are handled. Essential protections always remain in place.',why:'Topic preferences name their consequence: an age-appropriate explanation, a conversation with a grown-up, or no discussion. Learning, reading, explanation style and rewards have their own clearly named settings. Parent choice cannot authorize harmful instructions or commercial persuasion.',limit:'Questions about being hurt or feeling unsafe retain supportive guidance toward a trusted adult. No AI safeguard is a guarantee.'},
 {id:'guidance',label:'Explanation style',tab:2,title:'Help that\nmakes sense.',summary:'Choose shorter sentences, familiar examples or a calmer explanation style.',why:'A bounded choice is easier to understand than an open-ended instruction box. The parent can see what will change, then save. Scaffolded learning means providing enough help for the next step, with room for the child to try.',limit:'These choices shape supported AI explanations. They do not rewrite the wording of illustrated books.'},
 {id:'rewards',label:'Stars & appearance',tab:2,title:'Their little world.\nYour choice.',summary:'Stars can unlock outfits and places. You decide whether rewards are enabled.',why:'The backpack is an optional destination. Try-on does not spend Stars; choosing an item requires a separate confirmation. Stars are earned through learning, with a daily limit of 25. They cannot be bought with money. Wishes do not expire and there are no streak penalties.',limit:'This demo begins with 18 sample Stars and a small selection from the native catalogue. No payment or real account is involved.'},
 {id:'setup',label:'Watch setup',tab:3,title:'Connected.\nOn your terms.',summary:'Connect a child’s profile to the paired Watch. Review access or disconnect it.',why:'A child profile and a Watch’s access are separate choices. Paired access remains available until revoked. Disconnect explains its scope before confirmation: it stops future server access, without unpairing Apple devices or deleting the parent account.',limit:'The current beta uses a Watch normally paired with an iPhone. Apple Family Setup is not supported. This website never connects to a device.'}
];
export const sampleActivities=[
 {id:'question',kind:'Questions',label:'Curiosity',title:'Why does the Moon change shape?',summary:'We see different parts of the Moon lit by the Sun.',time:'9:35 AM'},
 {id:'math',kind:'Math',label:'Math',title:'Counting in the garden',summary:'3 of 5 jobs completed independently.',time:'9:20 AM'},
 {id:'story',kind:'Stories',label:'Story',title:'Pip and the Patient Seed',summary:'Finished a story about patience and a growing seed.',time:'9:05 AM'}
];
export function parentScreen(id='overview',s=initialParentState()){
 let title='Trustin Jr.',body='',tab=parentChapters.find(c=>c.id===id)?.tab||0;
 const child=['Explorer','Adventurer'][s.child],range=['Today','This week'][s.range];
 const profile='<div class="ios-profile">'+button('child',child+' ⌃')+button('range',range+' ⌃')+'<p class="ios-caption">Updated 9:41 AM · iPhone time</p></div>';
 const titleBlock=(heading,sub='')=>'<div class="ios-title"><div><h3>'+heading+'</h3>'+(sub?'<p class="ios-subtitle">'+sub+'</p>':'')+'</div>'+(heading==='Overview'?'<img src="/assets/trustin.png" width="300" height="353" alt="">':'')+'</div>';
 const activity=a=>'<button class="ios-activity" data-parent-action="detail-'+a.id+'"><div><b>'+a.label+'</b><span>'+a.time+'</span></div><strong>'+a.title+'</strong><p>'+a.summary+'</p></button>';
 const available=sampleActivities.filter(a=>!s.deleted.includes(a.id));
 const learning=()=>group('Math difficulty','<label class="ios-select-label">Starting band<select data-parent-setting="band" aria-label="Math starting band">'+mathBands.map((v,i)=>'<option value="'+i+'" '+(s.band===i?'selected':'')+'>'+v+'</option>').join('')+'</select></label><label class="ios-select-label">Step<select data-parent-setting="step" aria-label="Step within the band">'+['Start gently','Build confidence','Stretch a little'].map((v,i)=>'<option value="'+i+'" '+(s.step===i?'selected':'')+'>Step '+(i+1)+' · '+v+'</option>').join('')+'</select></label><p>'+mathBandDetails[s.band]+'</p>','learning')+'<p class="ios-caption">Applies to the next new Math project. Unfinished work, practice history and Stars are kept.</p>'+button('saveMath','Save starting point');
 const reading=()=>group('Story reading','<p>Reading speed</p><div class="ios-speed">'+['Slower','Calm','Natural'].map((v,i)=>'<button data-parent-action="speed-'+i+'" aria-pressed="'+(s.speed===i)+'">'+v+'</button>').join('')+'</div>'+button('sample','▷ Hear sample')+button('saveReading','Save reading speed')+'<p class="ios-caption">Saved on this phone, then applied when the paired Watch connects.</p>','reading');
 if(id==='overview'){
  body=titleBlock('Overview',child+'’s learning, at a glance.')+'<div data-parent-target="overview">'+profile+'<h4>Activity · '+range+'</h4><div class="ios-metrics">'+[['Questions','messages',s.child?1:s.range?6:2],['Math','sliders',s.range?3:1],['Stories','book',s.range?2:1]].map(([label,icon,n])=>'<button data-parent-action="filter-'+label+'">'+glyph(icon)+'<strong>'+n+'</strong><span>'+label+'</span></button>').join('')+'</div>'+button('reportGuide','ⓘ What appears here?')+(s.reportGuide?'<p class="ios-caption">Saved questions, Math projects and completed stories. Offline discovery listening is not included.</p>':'')+'</div>'+group('Math practice','<p><strong>3 of 5</strong> recorded jobs completed independently.</p>'+button('detail-math','View practiced skills'))+'<div class="ios-row ios-recent"><strong>Latest activity</strong>'+button('activity','View all')+'</div>'+available.map(activity).join('');
 }else if(id==='activity'){
  title=s.detail?'Activity detail':'Trustin Jr.';
  if(s.detail){const a=sampleActivities.find(x=>x.id===s.detail);body=button('back','‹ Activity')+'<div data-parent-target="activity"><h3 class="ios-detail-title">'+a.title+'</h3><p class="ios-caption">'+child+' · Today at '+a.time+'</p>'+(a.id==='question'?'<h4>Question</h4><p>Why does the Moon change shape?</p><h4>Trustin’s answer</h4><p>The Moon stays round like a ball. As it travels around Earth, we see different parts of its sunlit side.</p>':a.id==='math'?'<h4>Practice</h4><p>3 jobs completed independently.<br>2 jobs completed with support.</p><h4>Practiced skills</h4><p>Counting, adding and taking away.</p><p class="ios-caption">Supported practice is useful. It is recorded separately from independent work.</p>':'<h4>Story completed</h4><p>Pip planted a seed, gave it water and sunlight, and waited for it to grow.</p><p class="ios-caption">A completion record, not a reading assessment.</p>')+(s.confirm?'<div class="ios-confirm"><p>Delete this activity?</p>'+button('cancelDelete','Keep')+button('delete','Delete')+'</div>':button('confirmDelete','Delete this activity'))+'</div>';}
  else{const filtered=available.filter(a=>(s.filter==='All'||a.kind===s.filter)&&(a.title+' '+a.summary).toLowerCase().includes(s.search.toLowerCase()));body=titleBlock('Activity','Look back at a learning moment.')+profile+'<div data-parent-target="activity"><label class="ios-search"><span class="sr-only">Search sample activity</span><input data-parent-search placeholder="Search activity" value="'+escape(s.search)+'"></label><div class="ios-filters">'+['All','Questions','Math','Stories'].map(label=>'<button data-parent-action="filter-'+label+'" aria-pressed="'+(s.filter===label)+'">'+label+'</button>').join('')+'</div><div data-activity-results>'+filtered.map(activity).join('')+(filtered.length?'':'<p class="ios-caption">No matching saved activity.</p>')+'</div>'+(s.deleted.length?button('restore','Restore sample records'):'')+'</div>';}
 }else if(id==='topics'){
  if(s.route==='topicList'){
   title='Topic preferences';const names=['Religion','Violence','Body development','Drugs and alcohol','Profanity','Politics and civics','Money and products'],values=['Ask a grown-up','Block discussion','Age-appropriate'];
   body=button('safeguards','‹ Safeguards')+group('Topic preferences',names.map((name,i)=>row(name,values[s.topics[i]??(i===1?1:i===4||i===6?2:0)],'topic-'+i)).join(''),'topics')+group('Always protected','<p>Essential protections remain in place.</p><p class="ios-caption">Supportive help-seeking is always available.</p>')+button('save','Save safeguards');
  }else body=titleBlock('Safeguards','Choose how Trustin responds.')+group('Child',button('child',child+' ⌃'))+'<div data-parent-target="topics">'+group('',row('Topic preferences','7 topics','topicList'))+group('Learning preferences',row('Learning & reading','Age, Math and story speed','learning')+row('Explanation style','Your guidance','guidance')+row('Rewards & appearance','Earned Stars, outfits','rewards'))+group('',row('Always protected','Essential protections','protections')+row('About your child’s data','Learn more','dataInfo'))+'</div>'+(s.notice?'<p class="ios-caption">'+s.notice+'</p>':'');
 }else if(id==='learning'||id==='reading'){
  title='Learning & reading';body=button('topics','‹ Safeguards')+(id==='learning'?group('Learning pace',row('Age','4–5 years'))+learning()+reading():reading()+learning());
 }else if(id==='guidance'){
  title='Explanation style';body=button('topics','‹ Safeguards')+group('Explanation style',row('Choose a style',['No extra guidance','Familiar everyday examples','Shorter sentences','Avoid scary imagery'][s.style],'style')+'<p class="ios-caption">Affects supported AI explanations. Storybook wording stays the same.</p>','guidance')+button('save','Save safeguards')+group('Always protected','<p>Essential protections stay in place.</p>');
 }else if(id==='rewards'){
  title='Rewards & appearance';body=button('topics','‹ Safeguards')+'<div data-parent-target="rewards">'+group('Rewards', '<button class="ios-switch-row" data-parent-action="rewardsToggle" role="switch" aria-checked="'+s.rewards+'"><span>Stars & rewards</span><i class="ios-switch '+(s.rewards?'is-on':'')+'"></i></button><p class="ios-caption">'+(s.rewards?'Earned Stars, outfits and places.':'Stars and the shop are off. Learning stays available.')+'</p>')+group('Stars','<div class="ios-stars">★ '+s.stars+'</div><p>Up to 25 Stars per day.</p><p class="ios-caption">Stars are earned, never bought. No ads. No streak penalties.</p>')+'</div>'+group('Belongings',sampleTreasures.filter(x=>s.owned.includes(x.id)).map(x=>row(x.name,s.outfit[x.slot]===x.id?'Wearing':'Yours')).join(''));
 }else if(id==='setup'){
  title='Watch setup';body=titleBlock('Watch setup','A connection you control.')+group('Child',button('child',child+' ⌃'))+'<div data-parent-target="setup">'+(s.connected?group('Connected Watch','<p><strong>Explorer’s Watch</strong></p><p class="ios-caption">Access remains until disconnected.</p>'+(s.disconnect?'<p>Stop this Watch’s future server access? This will not unpair your Apple devices.</p>'+button('cancelDisconnect','Keep connected')+button('disconnect','Disconnect'):button('confirmDisconnect','Disconnect Watch'))):group('Connect Watch','<p>'+(s.prepared?'Ready for the paired Watch. Keep both apps open.':'Open Trustin Jr. on the paired Watch.')+'</p>'+button(s.prepared?'send':'prepare',s.prepared?'Send to Watch':'Prepare connection')))+'</div><p class="ios-caption">Paired iPhone + Apple Watch. Family Setup is not supported in this beta.</p>';
 }
 const tabs=[['grid','Overview','overview'],['clock','Activity','activity'],['shield','Safeguards','topics'],['watch','Watch setup','setup']];
 return '<div class="ios-status"><span>9:41</span><span class="ios-island"></span><span>▰</span></div><div class="ios-nav-title">'+title+'</div><div class="ios-scroll" tabindex="0" aria-label="'+title+' sample content">'+body+(s.notice&&id!=='topics'?'<p class="ios-caption ios-notice" role="status">'+s.notice+'</p>':'')+'</div><div class="ios-tabs" role="group" aria-label="Parent app navigation">'+tabs.map(([icon,label,key],i)=>'<button data-parent-action="'+key+'" '+(tab===i?'class="ios-selected" aria-pressed="true"':'aria-pressed="false"')+'>'+glyph(icon)+'<span>'+label+'</span></button>').join('')+'</div><div class="ios-home-bar"></div>';
}
